// Create a min-heap priority queue to build the Huffman tree
std::priority_queue<TreeNode*, std::vector<TreeNode*>, CompareTreeNode> minHeap;

// Create leaf nodes for each value-frequency pair and add to the min-heap
for (int i = 0; i < size; ++i) {
    TreeNode* node = new TreeNode(values[i], freqs[i]);
    minHeap.push(node);
}

// Build the Huffman tree by combining nodes until only one node remains
while (minHeap.size() > 1) {
    // Extract the two nodes with the smallest frequencies
    TreeNode* left = minHeap.top();
    minHeap.pop();
    TreeNode* right = minHeap.top();
    minHeap.pop();

    // Create a new internal node with the sum of frequencies
    // The value is set to -1 to indicate it's not a leaf node
    double combinedFreq = left->frequency + right->frequency;
    TreeNode* internalNode = new TreeNode(-1, combinedFreq);
    internalNode->left = left;
    internalNode->right = right;

    // Add the new node back to the min-heap
    minHeap.push(internalNode);
}

// The remaining node is the root of the Huffman tree
return minHeap.empty() ? nullptr : minHeap.top();

